/* QuickSight */
SELECT ds.* FROM ( select distinct reporting_period from alternative_assets_dev.listed_real_assets_bloomberg_attribution_by_country ) ds LIMIT 0

/* cppi::17f70f0198bf7b7cf33b145940bc6c7c9c70728a5161c4686e59dfe6779aa3cc */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-03' and end_date = '2025-04-03')
and start_date = '2025-04-03' and end_date = '2025-04-03'

/* cppi::9334b633b01fea3944f04a73f709b583afb3b321df58ecc6af5432d05cc48762 */
SELECT "COL"
FROM (SELECT 1 AS "COL") AS "SUBQUERY"

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

